// TypeScript Version: 4.1

/**
* Interface describing the GELU function with attached methods.
*/
interface GELU {
	/**
	* Evaluate the Gaussian Error Linear Unit (GELU) activation function.
	*
	* @param x - input value
	* @returns function value
	*
	* @example
	* var y = gelu( 0.0 );
	* // returns 0.0
	*
	* @example
	* var y = gelu( 1.0 );
	* // returns ~0.8413
	*
	* @example
	* var y = gelu( -Infinity );
	* // returns -0.0
	*
	* @example
	* var y = gelu( NaN );
	* // returns NaN
	*/
	( x: number ): number;

	/**
	* Evaluate the Gaussian Error Linear Unit (GELU) activation function using a tanh approximation.
	*
	* @param x - input value
	* @returns function value
	*
	* @example
	* var y = gelu.tanh( 0.0 );
	* // returns 0.0
	*
	* @example
	* var y = gelu.tanh( 1.0 );
	* // returns ~0.8412
	*
	* @example
	* var y = gelu.tanh( -Infinity );
	* // returns -0.0
	*
	* @example
	* var y = gelu.tanh( NaN );
	* // returns NaN
	*/
	tanh( x: number ): number;

	/**
	* Evaluate the Gaussian Error Linear Unit (GELU) activation function using a quick 1.702 approximation.
	*
	* @param x - input value
	* @returns function value
	*
	* @example
	* var y = gelu.quick( 0.0 );
	* // returns 0.0
	*
	* @example
	* var y = gelu.quick( 1.0 );
	* // returns ~0.8458
	*
	* @example
	* var y = gelu.quick( -Infinity );
	* // returns -0.0
	*
	* @example
	* var y = gelu.quick( NaN );
	* // returns NaN
	*/
	quick( x: number ): number;
}

/**
* Evaluate the Gaussian Error Linear Unit (GELU) activation function.
*
* @param x - input value
* @returns function value
*
* @example
* var y = gelu( 0.0 );
* // returns 0.0
*
* @example
* var y = gelu( 1.0 );
* // returns ~0.8413
*
* @example
* var y = gelu( -Infinity );
* // returns -0.0
*
* @example
* var y = gelu( NaN );
* // returns NaN
*
* @example
* var y = gelu.tanh( 0.0 );
* // returns 0.0
*
* @example
* var y = gelu.quick( 0.0 );
* // returns 0.0
*/
declare var gelu: GELU;


// EXPORTS //

export = gelu;
